								<td align="left" valign="middle">
									<b><a href="http://masslinemedia.com/smf/index.php?topic=89.msg2004#msg2004">Re: &quot;Questioning Freedom&quot; mentions Geologic/Blue Scholars</a></b>
									<div class="smalltext">&#171; <b>Reply #36 on:</b> October 21, 2006, 01:01:38 pm &#187;</div></td>
								<td align="right" valign="bottom" height="20" nowrap="nowrap" style="font-size: smaller;">
